changeSet.sql:
-- One row per eligible estate: the listing card and the header of -- the detail page. Seller is branch . company (MP-7): names only. CREATE VIEW marketplace_listings WITH (security_barrier = true) AS SELECT e.id AS estate_id, e.name AS name, e.area AS area, e.city AS city, e.state AS state, e.description AS description, e.image_url AS image_url, e.intent AS intent, e.corner_premium_pct AS corner_premium_pct, e.published_at AS published_at, e.footprint AS footprint, t.title_type AS title_type, b.name AS branch_name, COALESCE(NULLIF(btrim(o.trading_name), ''), o.registered_name) AS company_name, v.last_verified_at AS last_verified_at, ft.price AS from_price, ft.currency AS from_price_currency, ft.price_per_sqm AS from_price_per_sqm, sz.min_size_sqm AS min_size_sqm, sz.max_size_sqm AS max_size_sqm, COALESCE(pr.plots_remaining, 0) AS plots_remaining FROM marketplace_estate_eligibility el JOIN estates e ON e.id = el.estate_id JOIN organizations o ON o.id = e.tenant_id LEFT JOIN branches b ON b.id = e.branch_id AND b.deleted = false LEFT JOIN estate_titles t ON t.estate_id = e.id AND t.deleted = false -- The most recent check that actually came back VERIFIED. Never a -- pending or not_checked one: absent verification stays absent. LEFT JOIN LATERAL ( SELECT max(c.last_verified_at) AS last_verified_at FROM estate_verification_checks c WHERE c.estate_id = e.id AND c.deleted = false AND c.status = 'VERIFIED' ) v ON true -- "From" price: the cheapest tier that still has a plot for sale, -- falling back to the cheapest tier overall when everything is -- sold (the frontend's fromPrice() rule). The tier's own base -- price: a corner premium only ever raises it. LEFT JOIN LATERAL ( SELECT pt.price, pt.currency, CASE WHEN pt.tier_type = 'LAND_SIZE' AND pt.size_sqm > 0 THEN round(pt.price / pt.size_sqm, 2) END AS price_per_sqm FROM price_tiers pt WHERE pt.estate_id = e.id AND pt.deleted = false ORDER BY EXISTS ( SELECT 1 FROM plots p WHERE p.price_tier_id = pt.id AND p.deleted = false AND p.status IN ('AVAILABLE_DEV', 'AVAILABLE_INV') ) DESC, pt.price ASC LIMIT 1 ) ft ON true LEFT JOIN LATERAL ( SELECT min(pt.size_sqm) AS min_size_sqm, max(pt.size_sqm) AS max_size_sqm FROM price_tiers pt WHERE pt.estate_id = e.id AND pt.deleted = false AND pt.tier_type = 'LAND_SIZE' ) sz ON true LEFT JOIN LATERAL ( SELECT count(*) AS plots_remaining FROM plots p WHERE p.estate_id = e.id AND p.deleted = false AND p.status IN ('AVAILABLE_DEV', 'AVAILABLE_INV') ) pr ON true WHERE el.eligible;
-- An eligible estate's price list. price_per_sqm is a display -- comparison only, and NULL for a UNIT_TYPE tier, never zero. CREATE VIEW marketplace_price_tiers WITH (security_barrier = true) AS SELECT pt.id AS tier_id, pt.estate_id AS estate_id, pt.size_sqm AS size_sqm, pt.label AS label, pt.price AS price, pt.currency AS currency, CASE WHEN pt.tier_type = 'LAND_SIZE' AND pt.size_sqm > 0 THEN round(pt.price / pt.size_sqm, 2) END AS price_per_sqm, (SELECT count(*) FROM plots p WHERE p.price_tier_id = pt.id AND p.deleted = false AND p.status IN ('AVAILABLE_DEV', 'AVAILABLE_INV')) AS plots_remaining, (SELECT round(avg(p.actual_area_sqm), 2) FROM plots p WHERE p.price_tier_id = pt.id AND p.deleted = false AND p.actual_area_sqm IS NOT NULL) AS actual_area_sqm FROM price_tiers pt JOIN marketplace_estate_eligibility el ON el.estate_id = pt.estate_id AND el.eligible WHERE pt.deleted = false;
-- An eligible estate's plots, for the map. The status collapse -- happens HERE: RESERVED and SOLD both become UNAVAILABLE inside -- the database, so the distinction (which reveals sales velocity -- to competitors) never reaches the application, let alone a -- buyer. Unavailable plots still appear, so the estate reads as a -- real place rather than a sales sheet. CREATE VIEW marketplace_plots WITH (security_barrier = true) AS SELECT p.id AS plot_id, p.estate_id AS estate_id, p.price_tier_id AS price_tier_id, p.plot_number AS plot_number, COALESCE(NULLIF(btrim(bl.label), ''), bl.name) AS block_name, p.is_corner AS is_corner, p.nominal_size_sqm AS nominal_size_sqm, p.actual_area_sqm AS actual_area_sqm, CASE WHEN p.status IN ('AVAILABLE_DEV', 'AVAILABLE_INV') THEN 'AVAILABLE' ELSE 'UNAVAILABLE' END AS availability, p.footprint AS footprint FROM plots p JOIN marketplace_estate_eligibility el ON el.estate_id = p.estate_id AND el.eligible LEFT JOIN blocks bl ON bl.id = p.block_id AND bl.deleted = false WHERE p.deleted = false;
-- Verification with its SOURCE (MP-5): a registry lookup and a -- human reading a PDF are different claims in front of a buyer. -- Only checks that exist; a missing row means nobody has looked, -- and nothing here manufactures a placeholder. Notes are excluded: -- free text a developer wrote for themselves. CREATE VIEW marketplace_verification_checks WITH (security_barrier = true) AS SELECT c.id AS check_id, c.estate_id AS estate_id, c.check_type AS check_type, c.status AS status, c.verification_source AS verification_source, c.last_verified_at AS last_verified_at FROM estate_verification_checks c JOIN marketplace_estate_eligibility el ON el.estate_id = c.estate_id AND el.eligible WHERE c.deleted = false;
CREATE VIEW marketplace_amenities WITH (security_barrier = true) AS SELECT a.id AS amenity_id, a.estate_id AS estate_id, a.name AS name FROM estate_amenities a JOIN marketplace_estate_eligibility el ON el.estate_id = a.estate_id AND el.eligible WHERE a.deleted = false;

changeSet.rollback:
DROP VIEW marketplace_amenities;
DROP VIEW marketplace_verification_checks;
DROP VIEW marketplace_plots;
DROP VIEW marketplace_price_tiers;
DROP VIEW marketplace_listings;

changeSet.sql:
REVOKE ALL ON marketplace_estate_eligibility, marketplace_listings, marketplace_price_tiers,
              marketplace_plots, marketplace_verification_checks, marketplace_amenities
    FROM PUBLIC;
REVOKE ALL ON marketplace_estate_eligibility, marketplace_listings, marketplace_price_tiers,
              marketplace_plots, marketplace_verification_checks, marketplace_amenities
    FROM ${appDbUsername};
GRANT SELECT ON marketplace_estate_eligibility, marketplace_listings, marketplace_price_tiers,
                marketplace_plots, marketplace_verification_checks, marketplace_amenities
    TO ${appDbUsername};

changeSet.rollback:
REVOKE SELECT ON marketplace_estate_eligibility, marketplace_listings, marketplace_price_tiers,
                 marketplace_plots, marketplace_verification_checks, marketplace_amenities
    FROM ${appDbUsername};
